import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);

function invalid() {
  throw new Error('Invalid context packet input');
}

export function packContext(sections, maxBytes) {
  if (!Array.isArray(sections) || !Number.isSafeInteger(maxBytes) || maxBytes < 0) invalid();

  const entries = [];
  const ids = new Set();
  for (let index = 0; index < sections.length; index += 1) {
    if (!own(sections, index)) invalid();
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section) ||
        !own(section, 'id') || !own(section, 'text') || !own(section, 'priority') || !own(section, 'required') ||
        typeof section.id !== 'string' || section.id.length === 0 || typeof section.text !== 'string' ||
        !Number.isSafeInteger(section.priority) || section.priority < 0 || typeof section.required !== 'boolean' ||
        ids.has(section.id)) invalid();
    ids.add(section.id);
    const frame = `### ${JSON.stringify(section.id)}\n${section.text}\n`;
    entries.push({id: section.id, required: section.required, priority: section.priority, index,
      frame, cost: Buffer.byteLength(frame, 'utf8')});
  }

  const included = [];
  const omittedSet = new Set();
  const frames = [];
  let bytes = 0;
  for (const entry of entries) {
    if (!entry.required) continue;
    if (bytes + entry.cost > maxBytes) throw new Error('Required sections exceed maxBytes');
    bytes += entry.cost;
    frames.push(entry.frame);
    included.push(entry.id);
  }
  const optional = entries.filter((entry) => !entry.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  for (const entry of optional) {
    if (bytes + entry.cost <= maxBytes) {
      bytes += entry.cost;
      frames.push(entry.frame);
      included.push(entry.id);
    } else {
      omittedSet.add(entry.id);
    }
  }
  return {text: frames.join(''), bytes, included, omitted: entries.filter((entry) => omittedSet.has(entry.id)).map((entry) => entry.id)};
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('Expected exactly one input JSON file');
  const payload = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  return packContext(payload.sections, payload.maxBytes);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.stdout.write(`${JSON.stringify(runCli())}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {packContext} from '../context-packet.js';

const frame = (id, text) => `### ${JSON.stringify(id)}\n${text}\n`;

test('strictly validates every entry before budget selection', () => {
  const valid = {id: 'ok', text: 'x', priority: 0, required: false};
  const invalidCases = [
    [[], -1], [{}, 0], [new Array(1), 0], [[null], 0], [[[]], 0],
    [[{...valid, id: ''}], 0], [[{...valid, text: 1}], 0], [[{...valid, priority: 1.2}], 0],
    [[{...valid, required: 0}], 0], [[{...valid, id: 'a'}, {...valid, id: 'a'}], 0],
    [[{id: 'a', text: 'x', priority: 0}], 0]
  ];
  for (const [sections, budget] of invalidCases) assert.throws(() => packContext(sections, budget), Error);
});

test('preserves special IDs, frozen input, framing, and original omission order', () => {
  const sections = Object.freeze([
    Object.freeze({id: '__proto__', text: '  keep\n', priority: 3, required: false}),
    Object.freeze({id: 'A\u0000雪', text: '', priority: 1, required: true}),
    Object.freeze({id: 'a', text: 'later', priority: 2, required: false})
  ]);
  const required = frame('A\u0000雪', '');
  const first = frame('__proto__', '  keep\n');
  const result = packContext(sections, Buffer.byteLength(required) + Buffer.byteLength(first));
  assert.deepEqual(result, {text: required + first, bytes: Buffer.byteLength(required + first), included: ['A\u0000雪', '__proto__'], omitted: ['a']});
  assert.equal(sections[0].text, '  keep\n');
});

test('CLI has exact success output and rejects bad invocation without stdout', () => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'context-packet-'));
  const script = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  try {
    const input = path.join(directory, 'input.json');
    fs.writeFileSync(input, JSON.stringify({sections: [{id: 'x', text: 'é', priority: 0, required: false}], maxBytes: 100}));
    const success = spawnSync(process.execPath, [script, input], {encoding: 'utf8'});
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, `${JSON.stringify(packContext([{id: 'x', text: 'é', priority: 0, required: false}], 100))}\n`);
    const failure = spawnSync(process.execPath, [script], {encoding: 'utf8'});
    assert.equal(failure.status, 2);
    assert.equal(failure.stdout, '');
    assert.notEqual(failure.stderr, '');
  } finally {
    fs.rmSync(directory, {recursive: true, force: true});
  }
});

