import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {packContext} from '../context-packet.js';

const frame = (id, text) => `### ${JSON.stringify(id)}\n${text}\n`;
const section = (id, text, priority, required) => ({id, text, priority, required});

function assertCliFailure(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('strictly validates every entry before budget selection', () => {
  const valid = section('ok', 'x', 0, false);
  const invalidCases = [
    [[], -1], [[], 1.1], [[], Infinity], [[], Number.MAX_SAFE_INTEGER + 1],
    [{}, 0], [new Array(1), 0], [[null], 0], [[[]], 0],
    [[{...valid, id: ''}], 0], [[{...valid, id: 1}], 0],
    [[{...valid, text: 1}], 0], [[{...valid, priority: -1}], 0],
    [[{...valid, priority: 1.2}], 0], [[{...valid, priority: Infinity}], 0],
    [[{...valid, priority: Number.MAX_SAFE_INTEGER + 1}], 0],
    [[{...valid, required: 0}], 0],
    [[{...valid, id: 'a'}, {...valid, id: 'a'}], 0],
    [[{id: 'a', text: 'x', priority: 0}], 0]
  ];
  for (const [sections, budget] of invalidCases) {
    assert.throws(() => packContext(sections, budget), Error);
  }
});

test('includes required sections in input order and rejects combined required overflow', () => {
  const low = section('low', 'L', 0, true);
  const high = section('high', 'H', 99, true);
  const text = frame('low', 'L') + frame('high', 'H');
  const budget = Buffer.byteLength(text);
  assert.deepEqual(packContext([low, high], budget), {
    text, bytes: budget, included: ['low', 'high'], omitted: []
  });
  assert.throws(() => packContext([low, high], budget - 1), Error);
});

test('reports omitted optional IDs in input order rather than priority order', () => {
  const sections = [
    section('first-low', 'too large', 1, false),
    section('second-high', 'too large', 9, false),
    section('third-mid', 'too large', 5, false)
  ];
  assert.deepEqual(packContext(sections, 0), {
    text: '', bytes: 0, included: [], omitted: ['first-low', 'second-high', 'third-mid']
  });
});

test('preserves special IDs, frozen input, framing, and original omission order', () => {
  const sections = Object.freeze([
    Object.freeze(section('__proto__', '  keep\n', 3, false)),
    Object.freeze(section('A\u0000雪', '', 1, true)),
    Object.freeze(section('a', 'later', 2, false))
  ]);
  const required = frame('A\u0000雪', '');
  const first = frame('__proto__', '  keep\n');
  const result = packContext(sections, Buffer.byteLength(required) + Buffer.byteLength(first));
  assert.deepEqual(result, {text: required + first, bytes: Buffer.byteLength(required + first), included: ['A\u0000雪', '__proto__'], omitted: ['a']});
  assert.equal(sections[0].text, '  keep\n');
});

test('CLI has exact success output and failure contracts', () => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'context-packet-'));
  const script = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  try {
    const input = path.join(directory, 'input.json');
    fs.writeFileSync(input, JSON.stringify({sections: [section('x', 'é', 0, false)], maxBytes: 100}));
    const success = spawnSync(process.execPath, [script, input], {encoding: 'utf8'});
    assert.equal(success.status, 0);
    assert.equal(success.stdout, '{"text":"### \\"x\\"\\né\\n","bytes":11,"included":["x"],"omitted":[]}\n');
    assert.equal(success.stderr, '');

    assertCliFailure(spawnSync(process.execPath, [script], {encoding: 'utf8'}));
    assertCliFailure(spawnSync(process.execPath, [script, input, 'extra'], {encoding: 'utf8'}));
    assertCliFailure(spawnSync(process.execPath, [script, path.join(directory, 'missing.json')], {encoding: 'utf8'}));

    const malformed = path.join(directory, 'malformed.json');
    fs.writeFileSync(malformed, '{');
    assertCliFailure(spawnSync(process.execPath, [script, malformed], {encoding: 'utf8'}));

    const nullPayload = path.join(directory, 'null.json');
    fs.writeFileSync(nullPayload, 'null');
    assertCliFailure(spawnSync(process.execPath, [script, nullPayload], {encoding: 'utf8'}));

    const invalid = path.join(directory, 'invalid.json');
    fs.writeFileSync(invalid, JSON.stringify({sections: [section('bad', 'x', '0', false)], maxBytes: 100}));
    assertCliFailure(spawnSync(process.execPath, [script, invalid], {encoding: 'utf8'}));

    const overflow = path.join(directory, 'overflow.json');
    fs.writeFileSync(overflow, JSON.stringify({sections: [section('required', 'x', 0, true)], maxBytes: 0}));
    assertCliFailure(spawnSync(process.execPath, [script, overflow], {encoding: 'utf8'}));
  } finally {
    fs.rmSync(directory, {recursive: true, force: true});
  }
});

test('importing the module does not run the CLI', () => {
  const script = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(pathToFileURL(script).href)};`], {encoding: 'utf8'});
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

