import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);

function invalid() {
  throw new Error('Invalid context packet input');
}

export function packContext(sections, maxBytes) {
  if (!Array.isArray(sections) || !Number.isSafeInteger(maxBytes) || maxBytes < 0) invalid();

  const entries = [];
  const ids = new Set();
  for (let index = 0; index < sections.length; index += 1) {
    if (!own(sections, index)) invalid();
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section) ||
        !own(section, 'id') || !own(section, 'text') || !own(section, 'priority') || !own(section, 'required') ||
        typeof section.id !== 'string' || section.id.length === 0 || typeof section.text !== 'string' ||
        !Number.isSafeInteger(section.priority) || section.priority < 0 || typeof section.required !== 'boolean' ||
        ids.has(section.id)) invalid();
    ids.add(section.id);
    const frame = `### ${JSON.stringify(section.id)}\n${section.text}\n`;
    entries.push({id: section.id, required: section.required, priority: section.priority, index,
      frame, cost: Buffer.byteLength(frame, 'utf8')});
  }

  const included = [];
  const omittedSet = new Set();
  const frames = [];
  let bytes = 0;
  for (const entry of entries) {
    if (!entry.required) continue;
    if (bytes + entry.cost > maxBytes) throw new Error('Required sections exceed maxBytes');
    bytes += entry.cost;
    frames.push(entry.frame);
    included.push(entry.id);
  }
  const optional = entries.filter((entry) => !entry.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  for (const entry of optional) {
    if (bytes + entry.cost <= maxBytes) {
      bytes += entry.cost;
      frames.push(entry.frame);
      included.push(entry.id);
    } else {
      omittedSet.add(entry.id);
    }
  }
  return {text: frames.join(''), bytes, included, omitted: entries.filter((entry) => omittedSet.has(entry.id)).map((entry) => entry.id)};
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('Expected exactly one input JSON file');
  const payload = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  return packContext(payload.sections, payload.maxBytes);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.stdout.write(`${JSON.stringify(runCli())}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

